package com.smarthealth.service;import com.smarthealth.model.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
public class MedicalReminder extends HealthService{private final PriorityQueue<Reminder> queue=new PriorityQueue<>(Comparator.comparing(Reminder::getTime));private final ConcurrentMap<Long,Reminder> active=new ConcurrentHashMap<>();public MedicalReminder(){super();}public synchronized Reminder schedule(long medicineId,LocalDateTime time,String frequency){Reminder r=new Reminder(0,medicineId,time,frequency,Reminder.NotificationStatus.PENDING);queue.add(r);active.put(r.getId(),r);return r;}public synchronized List<Reminder> upcoming(int limit){return queue.stream().sorted(Comparator.comparing(Reminder::getTime)).limit(limit).toList();}public HealthResult analyzeHealth(SensorData d){return null;}public void performService(){log.info("Reminder service ready");}}
